// Pure, deterministic coin-dash simulation (no rendering, no DOM).

export type Status = "playing" | "paused" | "won" | "lost";

export const FIXED_DT = 1 / 60;
export const ROUND_SECONDS = 30;
export const ROUND_TICKS = ROUND_SECONDS * 60;
export const WIN_SCORE = 15;
export const COIN_COUNT = 10;
export const ARENA_HALF_X = 9;
export const ARENA_HALF_Z = 5;
export const PLAYER_RADIUS = 0.5;
export const COIN_RADIUS = 0.45;
export const PLAYER_SPEED = 7;
const SEED = 20240607;

export interface Vec2 {
  x: number;
  z: number;
}

export interface InputState {
  left: boolean;
  right: boolean;
  up: boolean;
  down: boolean;
}

function mulberry32(seed: number): () => number {
  let a = seed >>> 0;
  return () => {
    a = (a + 0x6d2b79f5) >>> 0;
    let t = a;
    t = Math.imul(t ^ (t >>> 15), t | 1);
    t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

export class CoinDashSim {
  readonly input: InputState = { left: false, right: false, up: false, down: false };
  readonly player: Vec2 = { x: 0, z: 0 };
  readonly coins: Vec2[] = [];
  score = 0;
  ticks = 0;
  paused = false;
  private outcome: "playing" | "won" | "lost" = "playing";
  private rng: () => number = mulberry32(SEED);

  constructor() {
    this.reset();
  }

  get status(): Status {
    if (this.outcome !== "playing") return this.outcome;
    return this.paused ? "paused" : "playing";
  }

  /** Elapsed simulated seconds. */
  get time(): number {
    return this.ticks * FIXED_DT;
  }

  get remaining(): number {
    return Math.max(0, ROUND_SECONDS - this.time);
  }

  reset(): void {
    this.rng = mulberry32(SEED);
    this.score = 0;
    this.ticks = 0;
    this.paused = false;
    this.outcome = "playing";
    this.player.x = 0;
    this.player.z = 0;
    this.coins.length = 0;
    for (let i = 0; i < COIN_COUNT; i++) this.coins.push(this.randomCoinPosition(i));
  }

  togglePause(): void {
    if (this.outcome !== "playing") return;
    this.paused = !this.paused;
  }

  /** Advance one fixed step. Does nothing while paused or after the round ended. */
  step(): void {
    if (this.outcome !== "playing" || this.paused) return;
    this.ticks++;

    let dx = (this.input.right ? 1 : 0) - (this.input.left ? 1 : 0);
    let dz = (this.input.down ? 1 : 0) - (this.input.up ? 1 : 0);
    if (dx !== 0 && dz !== 0) {
      dx *= Math.SQRT1_2;
      dz *= Math.SQRT1_2;
    }
    const maxX = ARENA_HALF_X - PLAYER_RADIUS;
    const maxZ = ARENA_HALF_Z - PLAYER_RADIUS;
    this.player.x = Math.min(maxX, Math.max(-maxX, this.player.x + dx * PLAYER_SPEED * FIXED_DT));
    this.player.z = Math.min(maxZ, Math.max(-maxZ, this.player.z + dz * PLAYER_SPEED * FIXED_DT));

    const reach = PLAYER_RADIUS + COIN_RADIUS;
    for (let i = 0; i < this.coins.length; i++) {
      const coin = this.coins[i];
      if (!coin) continue;
      const ddx = coin.x - this.player.x;
      const ddz = coin.z - this.player.z;
      if (ddx * ddx + ddz * ddz <= reach * reach) {
        this.score++;
        this.coins[i] = this.randomCoinPosition(i);
        if (this.score >= WIN_SCORE) {
          this.outcome = "won";
          return;
        }
      }
    }

    if (this.ticks >= ROUND_TICKS) this.outcome = "lost";
  }

  private randomCoinPosition(skipIndex: number): Vec2 {
    const marginX = ARENA_HALF_X - 1;
    const marginZ = ARENA_HALF_Z - 1;
    let candidate: Vec2 = { x: 0, z: 0 };
    for (let attempt = 0; attempt < 60; attempt++) {
      candidate = {
        x: (this.rng() * 2 - 1) * marginX,
        z: (this.rng() * 2 - 1) * marginZ
      };
      const farFromPlayer = Math.hypot(candidate.x - this.player.x, candidate.z - this.player.z) > 2.5;
      const farFromCoins = this.coins.every(
        (other, index) => index === skipIndex || Math.hypot(candidate.x - other.x, candidate.z - other.z) > 1.6
      );
      if (farFromPlayer && farFromCoins) return candidate;
    }
    return candidate;
  }
}

import { camera, createAuraApp, game, lights, material, primitives, scene } from "@aura3d/engine";
import type { AuraApp, AuraRuntimeNodeHandle } from "@aura3d/engine";
import {
  ARENA_HALF_X,
  ARENA_HALF_Z,
  CoinDashSim,
  COIN_COUNT,
  FIXED_DT,
  type Status
} from "./sim";

declare global {
  interface Window {
    __EVAL__?: {
      state: () => { score: number; status: Status; time: number };
      step: (frames: number) => void;
    };
    __EVAL_READY__?: boolean;
  }
}

const sim = new CoinDashSim();

// ---------------------------------------------------------------- HUD (DOM)
const hud = document.createElement("div");
hud.id = "hud";
hud.style.cssText = "display:flex;gap:16px;padding:6px 8px;font:600 14px/1.4 system-ui,sans-serif;";
hud.innerHTML =
  `<span>Score: <span id="score">0</span></span>` +
  `<span>Time: <span id="time">30.0</span></span>` +
  `<span>Status: <span id="status">playing</span></span>` +
  `<span style="opacity:.6;font-weight:400">WASD/arrows move · P pause · R restart</span>`;
document.body.append(hud);
const scoreEl = hud.querySelector<HTMLElement>("#score");
const timeEl = hud.querySelector<HTMLElement>("#time");
const statusEl = hud.querySelector<HTMLElement>("#status");

function renderHud(): void {
  if (scoreEl) scoreEl.textContent = String(sim.score);
  if (timeEl) timeEl.textContent = sim.remaining.toFixed(1);
  if (statusEl) statusEl.textContent = sim.status;
}

// ------------------------------------------------------------------ Input
const KEY_MAP: Record<string, keyof typeof sim.input> = {
  ArrowLeft: "left",
  KeyA: "left",
  ArrowRight: "right",
  KeyD: "right",
  ArrowUp: "up",
  KeyW: "up",
  ArrowDown: "down",
  KeyS: "down"
};

window.addEventListener("keydown", (event) => {
  const dir = KEY_MAP[event.code];
  if (dir) {
    sim.input[dir] = true;
    event.preventDefault();
    return;
  }
  if (event.repeat) return;
  if (event.code === "KeyP") {
    sim.togglePause();
    renderHud();
  } else if (event.code === "KeyR") {
    sim.reset();
    syncNodes();
    renderHud();
  }
});

window.addEventListener("keyup", (event) => {
  const dir = KEY_MAP[event.code];
  if (dir) sim.input[dir] = false;
});

window.addEventListener("blur", () => {
  sim.input.left = sim.input.right = sim.input.up = sim.input.down = false;
});

// -------------------------------------------------------------- Rendering
let playerNode: AuraRuntimeNodeHandle | undefined;
const coinNodes: AuraRuntimeNodeHandle[] = [];
let app: AuraApp | undefined;

function buildScene() {
  const s = scene({ background: "#0b1020" })
    .add(lights.ambient({ intensity: 0.6 }))
    .add(lights.directional({ position: [6, 14, 8], target: [0, 0, 0], intensity: 2.2 }))
    .add(
      primitives.plane({
        name: "arena floor",
        size: [ARENA_HALF_X * 2, 1, ARENA_HALF_Z * 2],
        position: [0, 0, 0],
        material: material.pbr({ color: "#24324f", roughness: 0.9 })
      })
    );

  const wall = (name: string, x: number, z: number, w: number, d: number) =>
    primitives.box({
      name,
      size: [w, 0.5, d],
      position: [x, 0.25, z],
      material: material.pbr({ color: "#5d7bb5", roughness: 0.6 })
    });
  s.add(wall("wall north", 0, -ARENA_HALF_Z - 0.15, ARENA_HALF_X * 2 + 0.6, 0.3));
  s.add(wall("wall south", 0, ARENA_HALF_Z + 0.15, ARENA_HALF_X * 2 + 0.6, 0.3));
  s.add(wall("wall west", -ARENA_HALF_X - 0.15, 0, 0.3, ARENA_HALF_Z * 2));
  s.add(wall("wall east", ARENA_HALF_X + 0.15, 0, 0.3, ARENA_HALF_Z * 2));

  s.add(
    primitives
      .sphere({
        name: "player",
        size: 1,
        position: [0, 0.5, 0],
        material: material.pbr({ color: "#3ec1ff", roughness: 0.35, metalness: 0.1 })
      })
      .runtime(game.runtimeNode("player", { tags: ["player"] }))
  );

  for (let i = 0; i < COIN_COUNT; i++) {
    const coin = sim.coins[i];
    s.add(
      primitives
        .cylinder({
          name: `coin ${i}`,
          size: [0.9, 0.14, 0.9],
          position: [coin?.x ?? 0, 0.6, coin?.z ?? 0],
          rotation: [Math.PI / 2, 0, 0],
          material: material.emissive({
            color: "#ffd54d",
            emissive: "#ffb300",
            emissiveIntensity: 1.5,
            roughness: 0.3
          })
        })
        .runtime(game.runtimeNode(`coin-${i}`, { tags: ["coin"] }))
    );
  }

  return s.camera(camera.perspective({ position: [0, 15, 7.5], target: [0, 0, 0.3], fov: 50 }));
}

function syncNodes(): void {
  playerNode?.setPosition(sim.player.x, 0.5, sim.player.z);
  const bob = Math.sin(sim.ticks * 0.08) * 0.08;
  for (let i = 0; i < coinNodes.length; i++) {
    const coin = sim.coins[i];
    if (coin) coinNodes[i]?.setPosition(coin.x, 0.6 + bob, coin.z);
  }
}

try {
  app = createAuraApp("#app", { scene: buildScene() });
  playerNode = app.nodes.require("player");
  for (let i = 0; i < COIN_COUNT; i++) coinNodes.push(app.nodes.require(`coin-${i}`));
} catch (error) {
  console.error("Aura3D render setup failed; simulation continues headless.", error);
}

// ------------------------------------------------- Fixed-step main loop
let accumulator = 0;
let lastTime: number | undefined;
let firstFrameDrawn = false;
let rendererReady = app === undefined;

void (app ? app.ready() : Promise.resolve())
  .catch(() => undefined)
  .then(() => {
    rendererReady = true;
  });

function frame(now: number): void {
  const elapsed = lastTime === undefined ? 0 : Math.min(0.25, (now - lastTime) / 1000);
  lastTime = now;

  if (sim.status === "playing") {
    accumulator += elapsed;
    while (accumulator >= FIXED_DT) {
      sim.step();
      accumulator -= FIXED_DT;
      if (sim.status !== "playing") {
        accumulator = 0;
        break;
      }
    }
  } else {
    accumulator = 0;
  }

  syncNodes();
  renderHud();

  if (!firstFrameDrawn && rendererReady) {
    firstFrameDrawn = true;
    window.__EVAL_READY__ = true;
  }
  requestAnimationFrame(frame);
}

window.__EVAL__ = {
  state: () => ({ score: sim.score, status: sim.status, time: sim.time }),
  step: (frames: number) => {
    const count = Math.max(0, Math.floor(frames));
    for (let i = 0; i < count; i++) sim.step();
    syncNodes();
    renderHud();
  }
};

renderHud();
requestAnimationFrame(frame);

